    "questions": [
      {
        "q": "Will Catherine burn Juliana's face after she says 'Burn it'?",
        "type": "intrigue"
      },
      {
        "q": "Why does Juliana suddenly stop fighting for the book?",
        "type": "confusion"
      }
    ],
    "standalone": {
      "score": 5,
      "reason": "Fully clear who is wronged (a chained, grieving Juliana), by whom (a sadistic Catherine), and what is at stakes (her mother's legacy and her own safety)."
    },
    "emotion": {
      "score": 5,
      "reason": "The gasping grief, the futile reach against chains, and the ember reflected in Juliana's pupil are gut punches of terror and anguish."
    },
    "want_next": {
      "score": 4,
      "reason": "The cruelty makes you desperately want justice, but the messy, overlong structure holds it back from a 5."
    },
    "ad_policy": {
      "level": "mild",
      "category": "violence",
      "reason": "A glowing branding iron is swung up toward Juliana's face and stops inches from her eyes."
    },
    "one_line_verdict": "A brutal, high-impact open and middle undone by an overlong, deflated finish."
  }
